import subprocess, os
os.chdir(os.path.dirname(os.path.abspath(__file__)) + '/..')
F = ['python', '../../../../tools/facts.py']


def add(name, claim, quote, date, status, note=None, vfv=None):
    a = F + ['add', '--prefix', 'G', '--name', name, '--claim', claim, '--quote', quote, '--page-date', date, '--status', status]
    if note:
        a += ['--note', note]
    if vfv:
        a += ['--visa', vfv[0], '--field', vfv[1], '--value', vfv[2]]
    r = subprocess.run(a, capture_output=True, text=True, encoding='utf-8')
    print((r.stdout + r.stderr).strip()[-160:], '|', claim[:80])


def provquote(prov):
    for line in open('sources/bancaditalia-rimesse-xlsx-2026-10.bangladesh.txt', encoding='utf-8'):
        if f'| {prov} | BD |' in line:
            return line[line.index(prov):].strip()


